css:
.table{overflow:visible}
.own{position:relative}
.own::after{content:''; position:absolute; inset:-16px 0 -14px;  /* 上下に突き抜ける */
  border:2px solid #ff2d78; border-radius:0; pointer-events:none}

/* 2つの枠の境界に矢印を跨がせる */
.arrow{position:absolute; left:50%; translate:-50% 0; z-index:2;
  width:0; height:0; border-left:6px solid transparent;
  border-right:6px solid transparent; border-bottom:10px solid #111}
.arrow::after{content:''; position:absolute; left:-2px; top:8px;
  width:4px; height:26px; background:#111}

/* 罫を越えて隣のセルへ入る装飾 */
.cell{position:relative; overflow:visible;
  border-right:1px solid #e6ddc9; border-bottom:1px solid #e6ddc9}
.cell .ring{position:absolute; left:-46px; z-index:2}
